  "modal.translate.checkingStatus": "\u041F\u0440\u043E\u0432\u0435\u0440\u043A\u0430 \u0441\u0442\u0430\u0442\u0443\u0441\u0430...",
  "modal.translate.noActive": "\u0410\u043A\u0442\u0438\u0432\u043D\u044B\u0439 \u043F\u0435\u0440\u0435\u0432\u043E\u0434 \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D (\u0432\u043E\u0437\u043C\u043E\u0436\u043D\u043E, \u0437\u0430\u0432\u0435\u0440\u0448\u0451\u043D).",
  "modal.translate.allPages": "\u0412\u0441\u0435 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B",
  "modal.translate.startPage": "\u0421\u043E \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B",
  "modal.translate.endPage": "\u041F\u043E \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0443",
  "modal.translate.startPageError": "\u041D\u0430\u0447\u0430\u043B\u044C\u043D\u0430\u044F \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0430 \u0434\u043E\u043B\u0436\u043D\u0430 \u0431\u044B\u0442\u044C \u2264 \u043A\u043E\u043D\u0435\u0447\u043D\u043E\u0439.",
  "modal.translate.backgroundRunning": "\u0424\u043E\u043D\u043E\u0432\u044B\u0439 \u043F\u0435\u0440\u0435\u0432\u043E\u0434 \u0443\u0436\u0435 \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u0435\u0442\u0441\u044F.",
  "modal.translate.errorPageCount": "\u041E\u0448\u0438\u0431\u043A\u0430: \u043D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0438\u0442\u044C \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u0441\u0442\u0440\u0430\u043D\u0438\u0446. {error}",
  "modal.translate.translationCancelled": "\u041F\u0435\u0440\u0435\u0432\u043E\u0434 \u043E\u0442\u043C\u0435\u043D\u0451\u043D. \u0422\u0435\u043A\u0443\u0449\u0430\u044F \u0437\u0430\u0434\u0430\u0447\u0430 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u0441\u044F; \u043D\u043E\u0432\u044B\u0435 \u0437\u0430\u0434\u0430\u0447\u0438 \u0437\u0430\u043F\u0443\u0441\u043A\u0430\u0442\u044C\u0441\u044F \u043D\u0435 \u0431\u0443\u0434\u0443\u0442. \u0423\u0436\u0435 \u0441\u043E\u0445\u0440\u0430\u043D\u0451\u043D\u043D\u044B\u0435 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F.",
  "modal.translate.workerInfo": "\u2139 \u041F\u0435\u0440\u0435\u0432\u043E\u0434 \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u0435\u0442\u0441\u044F \u0432 \u0444\u043E\u043D\u0435 \u0447\u0435\u0440\u0435\u0437 worker. PDF \u043D\u0435 \u043D\u0443\u0436\u043D\u043E \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0442\u044C. \u041C\u043E\u0436\u043D\u043E \u0437\u0430\u043A\u0440\u044B\u0442\u044C \u044D\u0442\u043E \u043E\u043A\u043D\u043E \u2014 \u043E\u0447\u0435\u0440\u0435\u0434\u044C \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0438\u0442 \u0440\u0430\u0431\u043E\u0442\u0443, \u0430 \u043F\u0440\u043E\u0433\u0440\u0435\u0441\u0441 \u043E\u0442\u043E\u0431\u0440\u0430\u0436\u0430\u0435\u0442\u0441\u044F \u0432 \u043E\u043A\u043D\u0435 \u043E\u0447\u0435\u0440\u0435\u0434\u0438 watcher (\u043A\u043E\u043C\u0430\u043D\u0434\u0430: \xAB\u0424\u043E\u043D\u043E\u0432\u044B\u0439 \u043F\u0435\u0440\u0435\u0432\u043E\u0434: \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u043E\u0447\u0435\u0440\u0435\u0434\u044C \u043E\u0442\u0441\u043B\u0435\u0436\u0438\u0432\u0430\u0435\u043C\u043E\u0439 \u043F\u0430\u043F\u043A\u0438\xBB).",
  "modal.translate.queueUnavailable": "\u041E\u0447\u0435\u0440\u0435\u0434\u044C worker \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u043D\u0430. \u041F\u043E\u043F\u0440\u043E\u0431\u0443\u0439\u0442\u0435 \u043F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u044C \u043F\u043B\u0430\u0433\u0438\u043D.",
  "modal.translate.allCached": "\u0412\u0441\u0435 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B {start}-{end} \u0443\u0436\u0435 \u043A\u044D\u0448\u0438\u0440\u043E\u0432\u0430\u043D\u044B. \u0423\u0434\u0430\u043B\u0438\u0442\u0435 .translations.md \u0434\u043B\u044F \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u043E\u0433\u043E \u0438\u0437\u0432\u043B\u0435\u0447\u0435\u043D\u0438\u044F.",
  "modal.translate.allCachedNothing": "\u0412\u0441\u0435 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B \u0443\u0436\u0435 \u043A\u044D\u0448\u0438\u0440\u043E\u0432\u0430\u043D\u044B. \u041D\u0435\u0447\u0435\u0433\u043E \u0434\u0435\u043B\u0430\u0442\u044C.",
  "modal.translate.queued": "\u0412 \u043E\u0447\u0435\u0440\u0435\u0434\u044C \u0434\u043E\u0431\u0430\u0432\u043B\u0435\u043D\u043E {count} \u0441\u0442\u0440\u0430\u043D\u0438\u0446(\u044B) [{start}-{end}]. Worker \u043E\u0431\u0440\u0430\u0431\u0430\u0442\u044B\u0432\u0430\u0435\u0442 \u0432 \u0444\u043E\u043D\u0435...",
  "modal.translate.started": "\u041F\u0435\u0440\u0435\u0432\u043E\u0434 \u043D\u0430\u0447\u0430\u0442: {count} \u0441\u0442\u0440\u0430\u043D\u0438\u0446(\u044B) \u0432 \u043E\u0447\u0435\u0440\u0435\u0434\u0438 \u0434\u043B\u044F \xAB{file}\xBB.",
  "modal.translate.completeNotice": "\u041F\u0435\u0440\u0435\u0432\u043E\u0434 \u0437\u0430\u0432\u0435\u0440\u0448\u0451\u043D: {done}/{total} \u0441\u0442\u0440\u0430\u043D\u0438\u0446 \u0434\u043B\u044F \xAB{file}\xBB.",
  "modal.translate.failedToStart": "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u044C: {error}",
  "modal.translate.failedToQueue": "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u043F\u043E\u0441\u0442\u0430\u0432\u0438\u0442\u044C \u0432 \u043E\u0447\u0435\u0440\u0435\u0434\u044C: {error}",
  "modal.translate.progress": "{done}/{total} \u0433\u043E\u0442\u043E\u0432\u043E, {pend} \u0432 \u043E\u0436\u0438\u0434\u0430\u043D\u0438\u0438",
  "modal.translate.progressWithError": "{done}/{total} \u0433\u043E\u0442\u043E\u0432\u043E, {err} \u043E\u0448\u0438\u0431\u043E\u043A, {pend} \u0432 \u043E\u0436\u0438\u0434\u0430\u043D\u0438\u0438",
  "modal.translate.finishedSummary": "\u2713 \u0417\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u043E: {done}/{total} \u0443\u0441\u043F\u0435\u0448\u043D\u043E, {err} \u043E\u0448\u0438\u0431\u043E\u043A.",
  "modal.translate.finishedSummaryOk": "\u2713 \u0417\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u043E: {done}/{total} \u0443\u0441\u043F\u0435\u0448\u043D\u043E.",
  "modal.translate.completeWithSummary": "\u041F\u0435\u0440\u0435\u0432\u043E\u0434 \u0437\u0430\u0432\u0435\u0440\u0448\u0451\u043D: {summary} \u0434\u043B\u044F \xAB{file}\xBB.",
  "modal.translate.starting": "\u23F3 \u0417\u0430\u043F\u0443\u0441\u043A \u0432\u043E\u0440\u043A\u0435\u0440\u0430 \u043F\u0435\u0440\u0435\u0432\u043E\u0434\u0430... \u043F\u043E\u0434\u043E\u0436\u0434\u0438\u0442\u0435.",
  "modal.translate.validation.startTooLow": "\u041D\u0430\u0447\u0430\u043B\u044C\u043D\u0430\u044F \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0430 \u0434\u043E\u043B\u0436\u043D\u0430 \u0431\u044B\u0442\u044C \u043D\u0435 \u043C\u0435\u043D\u0435\u0435 1.",
